const n = parseInt(readLine() ?? '0', 10);
const intervals = [];
for (let i = 0; i < n; i++) {
  const line = readLine() ?? '';
  const [start, end] = line.trim().split(/\s+/).map(Number);
  intervals.push([start, end]);
}

